    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int n = (int) in.nval;
        in.nextToken();
        int q = (int) in.nval;
        long[] xs = new long[n], ys = new long[n], radii = new long[q];
        for (int i = 0; i < n; i++) {
            in.nextToken(); xs[i] = (long) in.nval;
            in.nextToken(); ys[i] = (long) in.nval;
        }
        for (int j = 0; j < q; j++) {
            in.nextToken(); radii[j] = (long) in.nval;
        }
        int[] res = countInside(xs, ys, radii);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < res.length; i++) sb.append(res[i]).append(i + 1 < res.length ? " " : "\n");
